function renderQuestion(){
 const q=askById(route.id);if(q?.hidden)return removedContent('ask');if(!accessibleRecord(q))return unavailable();
 let h=`${q.hiddenByMe?hiddenStrip(q):''}<article class="question"><div class="row"><span class="avatar ${q.mine?'me':''}">${esc(q.ini)}</span><div class="grow"><b class="small">${esc(q.mine?state.profile.name:q.who)}</b><p class="tiny muted">${esc(q.ctx||q.city)}${q.edited?' · editada':''}</p></div>${iconBtn(q.following?'notifications_active':'notifications_none','follow-question',q.id,q.following?'Parar de seguir respostas':'Seguir respostas')}</div><h1>${esc(q.q)}</h1><div class="row between"><span>${pill(q.status==='ok'?'Resolvida':q.answers.length?`${q.answers.length} respostas`:'Sem resposta',q.status==='ok'?'ok':'')}</span>${iconBtn('share','share',`pergunta|${q.id}`,'Compartilhar indicação')}</div></article><section class="section">${sectionTitle('Respostas')}<div class="stack">`;
 if(!q.answers.length)h+=empty('A comunidade ainda não respondeu','Sua pergunta já está disponível. Você pode acompanhar as respostas por aqui.','forum');
 h+=q.answers.map(a=>`<article class="answer ${a.solved?'accepted':''}"><div class="row"><span class="avatar ${a.mine?'me':''}">${esc(a.ini||initals(a.who))}</span><div class="grow"><b class="small">${esc(a.mine?state.profile.name:a.who)}</b><p class="tiny muted">${a.mine?'Sua indicação':'Membro da comunidade'}${a.edited?' · editada':''}</p></div>${a.solved?pill('Ajudou a resolver','ok','check_circle'):''}${a.mine&&!readonly()?iconBtn('more_vert','answer-menu',`${q.id}|${a.id}`,'Opções da resposta'):''}</div><p class="detail-copy">${esc(a.t)}</p>${a.biz&&bizById(a.biz)?`<button type="button" class="answer-origin" data-action="open-biz" data-value="${a.biz}">${icon('storefront')}<span class="grow">${esc(bizById(a.biz).name)}</span>${icon('chevron_right')}</button>`:''}<div class="answer-actions">${q.mine?btn(a.solved?'Reabrir pergunta':'Ajudou a resolver',a.solved?'reopen-question':'solve-question',`${q.id}|${a.id}`,'tonal',a.solved?'refresh':'check_circle'):btn(`Útil${a.helped?' · '+a.helped:''}`,'like-answer',`${q.id}|${a.id}`,a.liked?'tonal':'text','thumb_up')}${btn('Ver origem','answer-origin',`${q.id}|${a.id}`,'text','history_edu')}</div></article>`).join('')+'</div></section>';
 if(q.status!=='ok'&&!readonly())h+=`<section class="question-compose"><h3>Compartilhe uma indicação</h3>${field('answer-input','Sua resposta','','type="textarea" rows="3" maxlength="2000"')}<div class="row" style="justify-content:flex-end">${btn('Enviar indicação','send-answer',q.id,'filled','send')}</div></section>`;
 const bs=matchingBiz(q.q);if(bs.length)h+=`<section class="section">${sectionTitle('Negócios relacionados')}<div class="list">${bs.map(b=>`<div class="list-row"><button type="button" class="txt" data-action="open-biz" data-value="${b.id}"><b>${esc(b.name)}</b><small>${esc(b.cat)}${b.spon?' · Patrocinado':''}</small></button>${btn('Orçamento','quote',b.id,'outlined','request_quote')}</div>`).join('')}</div></section>`;
 h+=`<section class="section">${btn('Denunciar pergunta','report',`ask|${q.id}`,'text','flag')}</section>`;return h;
}
